//Initialize everything when DOM is ready document.addEventListener('DOMContentLoaded',()=>{//Hide loading screen setTimeout(()=>{document.getElementById('loadingScreen').classList.add('hidden');},1000);//Header scroll effect const header=document.getElementById('header');window.addEventListener('scroll',()=>{if(window.scrollY>50){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}});//Mobile menu toggle const menuToggle=document.getElementById('menuToggle');const navMenu=document.getElementById('navMenu');menuToggle.addEventListener('click',()=>{menuToggle.classList.toggle('active');navMenu.classList.toggle('active');});//─── Mobilní carousel pro sekci Realizace ─────────────────────────(function initRealizaceCarousel(){const carousel=document.getElementById('demo');if(!carousel)return;const track=carousel.querySelector('.carousel-track');const slides=carousel.querySelectorAll('.carousel-item');const indicators=carousel.querySelectorAll('.carousel-indicators button');const prevBtn=carousel.querySelector('.carousel-control-prev');const nextBtn=carousel.querySelector('.carousel-control-next');if(!track || slides.length===0)return;let currentIndex=0;let autoplayTimer=null;let startX=0;let isDragging=false;let dragStartX=0;const AUTOPLAY_MS=4000;//Přejde na slide s indexem function goTo(index){if(index<0)index=slides.length-1;if(index>=slides.length)index=0;currentIndex=index;track.style.transform=`translateX(-${currentIndex*100}%)`;track.classList.remove('dragging');indicators.forEach((dot,i)=>{dot.classList.toggle('active',i===currentIndex);});}function move(direction){goTo(currentIndex+direction);resetAutoplay();}//─── Autoplay ─────────────────────────────────────────────── function startAutoplay(){stopAutoplay();autoplayTimer=setInterval(()=>goTo(currentIndex+1),AUTOPLAY_MS);}function stopAutoplay(){if(autoplayTimer){clearInterval(autoplayTimer);autoplayTimer=null;}}function resetAutoplay(){stopAutoplay();startAutoplay();}//─── Události ─────────────────────────────────────────────── if(prevBtn)prevBtn.addEventListener('click',()=>move(-1));if(nextBtn)nextBtn.addEventListener('click',()=>move(1));indicators.forEach(dot=>{dot.addEventListener('click',()=>{goTo(parseInt(dot.dataset.slide));resetAutoplay();});});//─── Drag/Swipe ────────────────────────────────────────── function onDragStart(clientX){isDragging=true;dragStartX=clientX;startX=clientX;track.classList.add('dragging');stopAutoplay();}function onDragMove(clientX){if(!isDragging)return;const diff=clientX-dragStartX;const pct=(diff/track.clientWidth)*100;track.style.transform=`translateX(calc(-${currentIndex*100}%+${pct}px))`;}function onDragEnd(clientX){if(!isDragging)return;isDragging=false;const diff=startX-clientX;track.classList.remove('dragging');if(Math.abs(diff)>50){goTo(currentIndex+(diff>0 ? 1:-1));}else{goTo(currentIndex);}startAutoplay();}//Dotyk track.addEventListener('touchstart',e=>onDragStart(e.touches[0].clientX),{passive:true});track.addEventListener('touchmove',e=>onDragMove(e.touches[0].clientX),{passive:true});track.addEventListener('touchend',e=>onDragEnd(e.changedTouches[0].clientX),{passive:true});//Myš(pro testování na desktopu)track.addEventListener('mousedown',e=>{onDragStart(e.clientX);e.preventDefault();});document.addEventListener('mousemove',e=>{if(isDragging)onDragMove(e.clientX);});document.addEventListener('mouseup',e=>{if(isDragging)onDragEnd(e.clientX);});//─── Resize ───────────────────────────────────────────────── let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(window.innerWidth>=768){stopAutoplay();track.style.transform='';}else{track.style.transform=`translateX(-${currentIndex*100}%)`;}},150);});//Inicializace goTo(0);startAutoplay();})();//Close mobile menu when clicking a link document.querySelectorAll('.nav-menu a').forEach(link=>{link.addEventListener('click',()=>{menuToggle.classList.remove('active');navMenu.classList.remove('active');});});//Smooth scrolling for anchor links document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){e.preventDefault();const targetId=this.getAttribute('href').slice(1);const target=document.getElementById(targetId);if(target){target.scrollIntoView({behavior:'smooth',block:'start'});}});});//Active menu highlighting on scroll const sections=document.querySelectorAll('section[id]');const navLinks=document.querySelectorAll('.nav-menu a');window.addEventListener('scroll',()=>{let current='';sections.forEach(section=>{const sectionTop=section.offsetTop;const sectionHeight=section.clientHeight;if(window.scrollY>=(sectionTop-200)){current=section.getAttribute('id');}});navLinks.forEach(link=>{link.classList.remove('active');if(link.getAttribute('href').slice(1)===current){link.classList.add('active');}});});//─── Kontaktní formulář ──────────────────────────────────────── const contactForm=document.getElementById('contactForm');if(contactForm){contactForm.querySelectorAll('.form-input').forEach(el=>{el.addEventListener('input',()=>{el.style.borderColor='';});});}//─── Lightbox ─────────────────────────────────────────────────(function initLightbox(){const lb=document.getElementById('lightbox');if(!lb)return;const lbImg=document.getElementById('lightboxImg');const lbCounter=document.getElementById('lightboxCounter');const lbClose=document.getElementById('lightboxClose');const lbPrev=document.getElementById('lightboxPrev');const lbNext=document.getElementById('lightboxNext');const sources=[{src:'images/realizace_21.jpg',alt:'Fasáda rodinného domu'},{src:'images/realizace_09.jpg',alt:'Zateplení dvojdomu'},{src:'images/realizace_11.jpg',alt:'Fasáda bytového domu'},{src:'images/realizace_14.jpg',alt:'Zednické práce Vilášek'},{src:'images/realizace_24.jpg',alt:'Moderní fasáda'},{src:'images/realizace_05.jpg',alt:'Fasáda bytového domu'},{src:'images/realizace_03.jpg',alt:'Zateplení bungalovu'},{src:'images/realizace_23.jpg',alt:'Fasáda rodinného domu'},{src:'images/realizace_25.jpg',alt:'Rekonstrukce přístavby'},];let current=0;function show(index){current=(index+sources.length)% sources.length;lbImg.style.opacity='0';setTimeout(()=>{lbImg.src=sources[current].src;lbImg.alt=sources[current].alt;lbCounter.textContent=(current+1)+'/'+sources.length;lbImg.style.opacity='1';},150);}function open(index){show(index);lb.style.display='flex';requestAnimationFrame(()=>{lb.style.opacity='1';});document.body.style.overflow='hidden';}function close(){lb.style.opacity='0';setTimeout(()=>{lb.style.display='none';},300);document.body.style.overflow='';}lbClose.addEventListener('click',close);lbPrev.addEventListener('click',()=>show(current-1));lbNext.addEventListener('click',()=>show(current+1));lb.addEventListener('click',e=>{if(e.target===lb)close();});document.addEventListener('keydown',e=>{if(lb.style.display !=='flex')return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1);});let lbTouchX=0;lb.addEventListener('touchstart',e=>{lbTouchX=e.touches[0].clientX;},{passive:true});lb.addEventListener('touchend',e=>{const diff=lbTouchX-e.changedTouches[0].clientX;if(Math.abs(diff)>50)diff>0 ? show(current+1):show(current-1);},{passive:true});document.querySelectorAll('.carousel-item').forEach((item,i)=>{item.addEventListener('click',()=>open(i));});document.querySelectorAll('.gallery-item').forEach((item,i)=>{item.addEventListener('click',()=>open(i));});})();//Reveal animations on scroll const revealElements=document.querySelectorAll('.reveal');const revealOnScroll=()=>{revealElements.forEach(element=>{const elementTop=element.getBoundingClientRect().top;const elementVisible=150;if(elementTop<window.innerHeight-elementVisible){element.classList.add('active');}});};window.addEventListener('scroll',revealOnScroll);revealOnScroll();//Check on load});